export function getTaskContent(title: string): TaskContent {
  const key = title.trim();
  const keyLower = key.toLowerCase();
  // Try exact match first, then substring match
  if (LIBRARY[key]) return LIBRARY[key];
  for (const libKey of Object.keys(LIBRARY)) {
    const libKeyLower = libKey.toLowerCase();
    if (keyLower.includes(libKeyLower) || libKeyLower.includes(keyLower)) return LIBRARY[libKey];
  }
  return GENERIC_CONTENT;
}
